<?php require __DIR__.'/bootstrap.php';
if(logged_in()){ header('Location:dashboard.php'); exit; }
$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $name=trim($_POST['name']??''); $email=trim(strtolower($_POST['email']??'')); $mobile=trim($_POST['mobile']??''); $course=trim($_POST['course']??''); $year=(int)($_POST['year']??0); $gender=$_POST['gender']??''; $password=$_POST['password']??'';
 if(!valid_name($name)||!filter_var($email,FILTER_VALIDATE_EMAIL)||!preg_match('/^[6-9][0-9]{9}$/',$mobile)||$course===''||$year<1||$year>6||!in_array($gender,['male','female','other','prefer_not_to_say'],true)||strlen($password)<8||$password!==($_POST['confirm_password']??'')||empty($_POST['terms'])) $errors[]='Please correct every field. Passwords must match and contain at least 8 characters.';
 $check=$pdo->prepare('SELECT id FROM users WHERE email=?');$check->execute([$email]); if($check->fetch())$errors[]='This email is already registered.';
 if(!$errors){$s=$pdo->prepare("INSERT INTO users(name,email,password_hash,role,mobile,course,year_of_study,gender) VALUES(?,?,?,'student',?,?,?,?)");$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$mobile,$course,$year,$gender]); flash('Account created. Please sign in.'); header('Location:index.php');exit;}
} page_top('Register'); ?>
<section class="auth-card"><h1>Create student account</h1><?php foreach($errors as $error):?><p class="flash error"><?=e($error)?></p><?php endforeach;?><form class="form-grid" method="post" id="registration-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Name<input required name="name" value="<?=e($_POST['name']??'')?>"></label><label>Email<input required type="email" name="email" value="<?=e($_POST['email']??'')?>"></label><label>Mobile<input required inputmode="numeric" pattern="[6-9][0-9]{9}" name="mobile" value="<?=e($_POST['mobile']??'')?>"></label><label>Course<input required name="course" value="<?=e($_POST['course']??'')?>"></label><label>Year<select required name="year"><option value="">Choose</option><?php for($i=1;$i<=6;$i++):?><option value="<?=$i?>" <?=($i==(int)($_POST['year']??0))?'selected':''?>><?=$i?></option><?php endfor;?></select></label><label>Gender<select required name="gender"><option value="">Choose</option><option value="male">Male</option><option value="female">Female</option><option value="other">Other</option><option value="prefer_not_to_say">Prefer not to say</option></select></label><label>Password<input required minlength="8" type="password" name="password"></label><label>Confirm password<input required minlength="8" type="password" name="confirm_password"></label><label class="full"><input required type="checkbox" name="terms"> I accept the portal terms.</label><button class="full">Register</button></form><p><a href="index.php">Back to sign in</a></p></section><?php page_bottom();
